var spiralMatrixIII = function(rows, cols, rStart, cStart) {
    const ans = [[rStart, cStart]];
    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let d = 0, step = 1;
    let r = rStart, c = cStart;
    while (ans.length < rows * cols) {
        for (let k = 0; k < 2; k++) {
            const [dr, dc] = dirs[d];
            for (let s = 0; s < step; s++) {
                r += dr;
                c += dc;
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
